const teachers = [
  {id:'meera',name:'Meera Iyer',initials:'MI',tone:'lav',grade:'Grade 11 · Bengaluru',subjects:['Mathematics','Physics'],language:'English, Hindi',rating:'4.9',reviews:28,rate:120,bio:'Making tricky concepts feel simple, one step at a time. I love visual explanations and real-world examples.',slots:['17:00','18:00','19:00'],days:['Mon','Wed','Fri'],tag:'Top mentor'},
  {id:'kabir',name:'Kabir Malhotra',initials:'KM',tone:'mint',grade:'Grade 10 · Delhi',subjects:['Coding','Robotics'],language:'English, Hindi',rating:'5.0',reviews:19,rate:100,bio:'Learn to build cool things with code. Friendly Python and Scratch sessions for curious beginners.',slots:['16:30','17:30','18:30'],days:['Tue','Thu','Sat'],tag:'Rising star'},
  {id:'ananya',name:'Ananya Rao',initials:'AR',tone:'peach',grade:'Grade 12 · Hyderabad',subjects:['Biology','Chemistry'],language:'English, Telugu',rating:'4.8',reviews:34,rate:150,bio:'Biology enthusiast who turns dense chapters into memorable stories and clear diagrams.',slots:['17:00','18:00'],days:['Mon','Thu','Sun'],tag:'Popular'},
  {id:'zoya',name:'Zoya Khan',initials:'ZK',tone:'blue',grade:'Grade 11 · Mumbai',subjects:['Art','Design'],language:'English, Hindi',rating:'4.9',reviews:16,rate:90,bio:'Explore drawing, colour and digital illustration in a relaxed and encouraging space.',slots:['16:00','17:00','18:00'],days:['Wed','Fri','Sat'],tag:'Creative'},
  {id:'ishaan',name:'Ishaan Patel',initials:'IP',tone:'gold',grade:'Grade 12 · Ahmedabad',subjects:['English','Public speaking'],language:'English, Gujarati',rating:'4.7',reviews:21,rate:110,bio:'Build confidence with clear writing, conversation practice and fun speaking activities.',slots:['17:30','18:30'],days:['Tue','Fri','Sun'],tag:'Great communicator'},
  {id:'tara',name:'Tara Nair',initials:'TN',tone:'lav',grade:'Grade 9 · Kochi',subjects:['Music','Guitar'],language:'English, Malayalam',rating:'4.9',reviews:12,rate:100,bio:'Beginner guitar lessons with favourite songs, friendly feedback and no-pressure practice.',slots:['16:30','17:30'],days:['Mon','Wed','Sat'],tag:'New mentor'}
];
const categories=[['∑','Mathematics','2.4k learners'],['⌘','Coding','1.8k learners'],['⚗','Science','1.6k learners'],['♫','Music','950 learners'],['✎','Art & design','820 learners'],['Aa','Languages','740 learners']];
const initialState={user:{name:'Aarav Sharma',role:'Learner',grade:'Grade 10'},plan:'Free',points:240,earned:320,spent:80,classesUsed:1,bookings:[{id:'b1',teacher:'meera',subject:'Mathematics',date:dayOffset(2),time:'17:00',sessions:1,status:'Confirmed',format:'Online'},{id:'b2',teacher:'kabir',subject:'Coding',date:dayOffset(5),time:'17:30',sessions:1,status:'Pending',format:'Online'}],notifications:[{title:'Class confirmed',body:'Meera accepted your Mathematics session.',time:'10 min ago',unread:true},{title:'You earned 40 Peer Points',body:'Thanks for completing a learning session!',time:'Yesterday',unread:true},{title:'New video in Science',body:'Ananya shared a new Biology lesson.',time:'Yesterday',unread:true}],videos:[{title:'Algebra made visual',subject:'Mathematics',teacher:'Meera Iyer',grade:'Grades 9–11',status:'Approved',icon:'∑'},{title:'Your first Python loop',subject:'Coding',teacher:'Kabir Malhotra',grade:'Grades 8–10',status:'Approved',icon:'⌘'},{title:'Cell biology in 5 minutes',subject:'Biology',teacher:'Ananya Rao',grade:'Grades 9–12',status:'Approved',icon:'⚗'},{title:'Colour and composition',subject:'Art',teacher:'Zoya Khan',grade:'All levels',status:'In review',icon:'✎'}],questions:[{title:'How do I remember the trigonometric identities?',subject:'Mathematics',asked:'Riya · 2 hours ago',answers:3,answer:'Try drawing a unit circle first. The signs and relationships become much easier to remember when you can see them.'},{title:'What is the difference between mitosis and meiosis?',subject:'Biology',asked:'Dev · Yesterday',answers:5,answer:'Mitosis makes two identical cells for growth. Meiosis makes four unique cells for reproduction.'},{title:'Where should I start with Python?',subject:'Coding',asked:'Nisha · Yesterday',answers:2,answer:'Start with variables and print statements, then make a tiny quiz. Small projects keep it fun!'}],privacy:{profile:true,guardian:true,offline:false,video:true}};
function dayOffset(n){const d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
let state;try{state={...initialState,...JSON.parse(localStorage.getItem('peerly-state')||'{}')};}catch{state={...initialState}}
state.user={...initialState.user,...state.user};let currentView='home',selectedTeacher=null,adminTab='overview',discoverQuery='',discoverSubject='All subjects',discoverGrade='Any grade';
const content=document.getElementById('content');
function save(){localStorage.setItem('peerly-state',JSON.stringify(state));updateUser()}
function updateUser(){document.getElementById('user-name').textContent=state.user.name;document.getElementById('user-role').textContent=`${state.user.role} · ${state.user.grade||'Grade 10'}`;document.getElementById('notification-count').textContent=state.notifications.filter(n=>n.unread).length||''}
function fmtDate(s,opts={weekday:'short',month:'short',day:'numeric'}){return new Intl.DateTimeFormat('en-IN',opts).format(new Date(s+'T12:00:00'))}
function initials(name){return name.split(' ').map(x=>x[0]).join('').slice(0,2)}
function avatar(name,tone='lav',size=''){return `<span class="avatar ${size==='small'?'avatar-small':''} avatar-${tone}">${initials(name)}</span>`}
function teacher(id){return teachers.find(t=>t.id===id)||teachers[0]}
function setView(view){currentView=view;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.getElementById('breadcrumb-current').textContent=({home:'Home',discover:'Discover',calendar:'My calendar',portfolio:'My portfolio',videos:'Video library',support:'Peer support',points:'Peer Points',plans:'Plans & membership',notifications:'Notifications',teach:'Teaching & learning',safety:'Safety & privacy',parent:'Parent portal',educator:'Educator portal',admin:'Admin dashboard'}[view]||'Home');document.getElementById('sidebar').classList.remove('open');render()}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){e.preventDefault();setView(nav.dataset.view)}const act=e.target.closest('[data-action]');if(act)handleAction(act.dataset.action,act.dataset.id);const cat=e.target.closest('[data-subject]');if(cat){discoverSubject=cat.dataset.subject;setView('discover')}});
document.getElementById('mobile-menu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');
document.getElementById('profile-switch').onclick=()=>openSwitcher();
document.getElementById('help-button').onclick=()=>openModal('PEERLY demo help',`<p>This interactive product preview stores your changes in this browser. Create a demo profile, request a class, and switch between learner, parent, educator, and admin views.</p><div class="notice">Authentication, guardian identity checks, video storage, moderation and payment processing are simulated. No private messages or real payments are sent.</div><button class="btn btn-primary" data-action="close-modal">Got it</button>`);
function render(){updateUser();const views={home:homeView,discover:discoverView,calendar:calendarView,portfolio:portfolioView,videos:videosView,support:supportView,points:pointsView,plans:plansView,notifications:notificationsView,teach:teachView,safety:safetyView,parent:parentView,educator:educatorView,admin:adminView};content.innerHTML=(views[currentView]||homeView)()}
function heading(title,sub='',right=''){return `<div class="page-heading"><div><div class="eyebrow">${currentView==='home'?'YOUR LEARNING SPACE':'PEERLY WORKSPACE'}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function teacherCard(t){return `<article class="teacher-card"><div class="teacher-top">${avatar(t.name,t.tone)}<div><h4>${t.name}</h4><div class="teacher-meta">${t.grade}</div><div class="verified">✦ Student-teacher · ${t.tag}</div></div></div><p class="teacher-description">${t.bio}</p><div class="teacher-tags">${t.subjects.map((s,i)=>`<span class="tag ${i?'teal':''}">${s}</span>`).join('')}<span class="tag orange">${t.language.split(',')[0]}</span></div><div class="teacher-foot"><div class="teacher-price"><span class="rating">★ ${t.rating}</span> (${t.reviews}) · <b>${t.rate}</b> pts/session</div><div class="teacher-actions"><button class="btn btn-quiet" data-action="profile" data-id="${t.id}">Profile</button><button class="btn btn-primary" data-action="book" data-id="${t.id}">Request</button></div></div></article>`}
function sessionRow(b){const t=teacher(b.teacher);return `<div class="session-row"><div class="session-date"><b>${new Date(b.date+'T12:00:00').getDate()}</b><small>${new Intl.DateTimeFormat('en-IN',{month:'short'}).format(new Date(b.date+'T12:00:00'))}</small></div><div class="session-info"><b>${b.subject} with ${t.name}</b><small>${b.format} · ${b.sessions} session${b.sessions>1?'s':''}</small></div><span class="session-time">${b.time}</span><span class="status-pill ${b.status==='Pending'?'status-pending':''}">${b.status}</span></div>`}
function homeView(){const upcoming=state.bookings.filter(b=>b.status!=='Declined').sort((a,b)=>a.date.localeCompare(b.date));return `${heading(`Good afternoon, ${state.user.name.split(' ')[0]} 👋`,'Your curiosity looks good on you. Ready to learn something new?',`<button class="date-chip">◷ &nbsp; ${fmtDate(dayOffset(0),{month:'long',day:'numeric',year:'numeric'})}</button>`)}<section class="hero"><div class="hero-copy"><div class="hero-kicker">BY STUDENTS. FOR STUDENTS.</div><h2>Learn from someone<br>who gets it.</h2><p>Discover what you can learn. Share what you know. Connect with students who help you grow.</p><div class="hero-actions"><button class="btn btn-primary" data-view="discover">I want to learn <span>↗</span></button><button class="btn btn-secondary" data-action="register">Get started</button><button class="btn btn-quiet" data-view="teach">I want to teach</button></div></div><div class="hero-art"><div class="art-orbit"></div><span class="art-spark s1">✦</span><span class="art-spark s2">✧</span><div class="art-card"><div class="art-cap">✳</div><b>Curiosity club</b><small>Learn together</small></div></div></section><div class="stat-grid"><div class="stat-card"><span class="stat-icon">▦</span><div><div class="stat-value">${state.bookings.filter(b=>b.status==='Confirmed').length+1}</div><div class="stat-label">Sessions this month</div></div></div><div class="stat-card"><span class="stat-icon">✳</span><div><div class="stat-value">${state.points}</div><div class="stat-label">Peer Points balance</div></div></div><div class="stat-card"><span class="stat-icon">✦</span><div><div class="stat-value">${state.plan}</div><div class="stat-label">Your membership</div></div></div><div class="stat-card"><span class="stat-icon">♧</span><div><div class="stat-value">${state.notifications.filter(n=>n.unread).length}</div><div class="stat-label">New notifications</div></div></div></div><div class="columns"><section class="panel"><div class="panel-title"><h3>Coming up for you</h3><button data-view="calendar">Full calendar →</button></div>${upcoming.slice(0,3).map(sessionRow).join('')||'<div class="empty-state"><span>▦</span><b>A little room for a new idea</b><p>Your upcoming classes will appear here.</p></div>'}</section><section class="panel"><div class="panel-title"><h3>Picked for you</h3><button data-view="discover">See all →</button></div>${teachers.slice(0,3).map(t=>`<div class="teacher-mini">${avatar(t.name,t.tone,'small')}<div class="teacher-mini-info"><b>${t.name}</b><small>${t.subjects.join(' · ')}</small></div><span class="rating">★ ${t.rating}</span></div>`).join('')}</section></div><div class="section-heading"><div><h3>Explore a new interest</h3><p>A small spark can lead somewhere big.</p></div><button class="text-link" data-view="discover">All subjects →</button></div><div class="category-grid">${categories.map(c=>`<button class="category-card" data-subject="${c[1]}"><div class="category-emoji">${c[0]}</div><b>${c[1]}</b><small>${c[2]}</small></button>`).join('')}</div><div class="section-heading"><div><h3>Peers to learn with</h3><p>Great people sharing what they know.</p></div><button class="text-link" data-view="discover">Explore marketplace →</button></div><div class="teacher-grid">${teachers.slice(0,3).map(teacherCard).join('')}</div>`}
function discoverView(){let list=teachers.filter(t=>(discoverSubject==='All subjects'||t.subjects.some(s=>s.toLowerCase().includes(discoverSubject.toLowerCase().split(' ')[0]))||discoverSubject==='Science'&&t.subjects.some(s=>['Physics','Biology','Chemistry'].includes(s)))&&(!discoverQuery||`${t.name} ${t.subjects.join(' ')} ${t.bio}`.toLowerCase().includes(discoverQuery.toLowerCase()))&&(discoverGrade==='Any grade'||t.grade.includes(discoverGrade)));return `${heading('Find your next favourite teacher','Good things happen when students learn together.',`<button class="btn btn-secondary" data-view="teach">Become a teacher +</button>`)}<div class="search-panel"><label class="search-wrap"><span>⌕</span><input id="discover-search" placeholder="Search skills, subjects or student-teachers..." value="${discoverQuery}"></label><select class="filter-select" id="subject-select"><option>All subjects</option>${['Mathematics','Coding','Science','Music','Art','Languages'].map(x=>`<option ${discoverSubject===x?'selected':''}>${x}</option>`).join('')}</select><select class="filter-select" id="grade-select"><option>Any grade</option>${[8,9,10,11,12].map(x=>`<option ${discoverGrade===`Grade ${x}`?'selected':''}>Grade ${x}</option>`).join('')}</select><button class="btn btn-primary" id="search-button">Search</button></div><div class="discover-layout"><aside class="filter-sidebar"><div class="filter-group"><h4>Popular subjects</h4>${['All subjects','Mathematics','Coding','Science','Music','Art','Languages'].map(s=>`<label class="filter-option"><input type="radio" name="side-subject" ${discoverSubject===s?'checked':''} value="${s}"> ${s}</label>`).join('')}</div><div class="filter-group"><h4>Availability</h4>${['After school','Weekends','Evenings'].map(s=>`<label class="filter-option"><input type="checkbox"> ${s}</label>`).join('')}</div><div class="filter-group"><h4>Learning format</h4><label class="filter-option"><input type="checkbox" checked> Online</label><label class="filter-option"><input type="checkbox"> School-approved offline</label></div></aside><div><div class="result-count">Showing <b>${list.length}</b> student-teacher${list.length===1?'':'s'} · ${discoverSubject}</div><div class="teacher-grid">${list.map(teacherCard).join('')||'<div class="empty-state"><span>⌕</span><b>No peers found just yet</b><p>Try another search or subject.</p></div>'}</div></div></div>`}
function calendarView(){const now=new Date(),year=now.getFullYear(),month=now.getMonth(),first=new Date(year,month,1),last=new Date(year,month+1,0),offset=(first.getDay()+6)%7;let cells='';['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].forEach(d=>cells+=`<div class="calendar-cell head">${d}</div>`);for(let i=0;i<offset;i++)cells+='<div class="calendar-cell"></div>';for(let d=1;d<=last.getDate();d++){const date=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,book=state.bookings.find(x=>x.date===date&&x.status!=='Declined');cells+=`<div class="calendar-cell"><span class="calendar-day ${d===now.getDate()?'today':''}">${d}</span>${book?`<div class="cal-event ${book.subject==='Coding'?'teal':''}">${book.time} · ${book.subject}</div>`:''}</div>`}return `${heading('My calendar','A little planning for a lot of learning.',`<button class="btn btn-primary" data-view="discover">+ Find a class</button>`)}<section class="panel"><div class="panel-title"><h3 class="calendar-title">${new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric'}).format(now)}</h3><div class="calendar-tools"><button class="btn btn-quiet" data-action="calendar-info">Today</button><button class="btn btn-quiet" data-action="calendar-info">‹</button><button class="btn btn-quiet" data-action="calendar-info">›</button></div></div><div class="calendar-grid">${cells}</div></section><div class="section-heading"><div><h3>Your scheduled sessions</h3><p>Session requests and confirmed classes.</p></div></div><section class="panel">${state.bookings.map(sessionRow).join('')||'<div class="empty-state"><span>▦</span><b>No sessions scheduled</b></div>'}</section>`}
function portfolioView(){return `${heading('My portfolio','Your learning story, all in one place.',`<button class="btn btn-secondary" data-action="edit-profile">Edit portfolio</button>`)}<section class="profile-hero">${avatar(state.user.name,'lav')}<div><div class="eyebrow">LEARNER · ${state.user.grade.toUpperCase()}</div><h2>${state.user.name}</h2><div class="teacher-meta">Curious learner · Joined this term</div><p class="profile-bio">I love exploring how things work, especially in math and science. Always up for learning something new!</p><div class="profile-stats"><span><b>${state.bookings.filter(b=>b.status==='Confirmed').length+4}</b> classes attended</span><span><b>${state.points}</b> Peer Points</span><span><b>3</b> skills exploring</span></div></div><button class="btn btn-quiet" data-action="share-portfolio">↗ Share portfolio</button></section><div class="columns"><section class="panel"><div class="panel-title"><h3>My learning journey</h3><button data-view="calendar">View all →</button></div><div class="progress-list"><div><div class="progress-line"><b>Mathematics</b><span>8 of 12 sessions</span></div><div class="progress-track"><div class="progress-fill" style="width:67%"></div></div></div><div><div class="progress-line"><b>Coding</b><span>4 of 8 sessions</span></div><div class="progress-track"><div class="progress-fill" style="width:50%;background:#4da899"></div></div></div><div><div class="progress-line"><b>Creative writing</b><span>3 of 6 sessions</span></div><div class="progress-track"><div class="progress-fill" style="width:50%;background:#e6a253"></div></div></div></div></section><section class="panel"><div class="panel-title"><h3>Skills & interests</h3><button data-action="edit-profile">+ Add</button></div><span class="tag">Mathematics</span><span class="tag teal">Coding</span><span class="tag orange">Drawing</span><div class="panel-title" style="margin:18px 0 10px"><h3>Achievements</h3></div><div class="teacher-mini"><span class="stat-icon">✦</span><div class="teacher-mini-info"><b>Curious mind</b><small>Completed 5 learning sessions</small></div></div><div class="teacher-mini"><span class="stat-icon">♡</span><div class="teacher-mini-info"><b>Peer supporter</b><small>Helped a fellow learner</small></div></div></section></div><div class="section-heading"><div><h3>Your recent learning</h3><p>Every session is a step forward.</p></div></div><section class="panel">${state.bookings.map(sessionRow).join('')}</section>`}
function videosView(){return `${heading('Video library','Bite-sized lessons made by students, for students.',`<button class="btn btn-primary" data-action="upload-video">↑ Share a video</button>`)}<div class="callout">Videos are reviewed before they become public. This demo shows sample lessons; uploaded video files are not stored.</div><div class="search-panel"><label class="search-wrap"><span>⌕</span><input id="video-search" placeholder="Search the library..."></label><select class="filter-select" id="video-subject"><option>All subjects</option>${['Mathematics','Coding','Biology','Art'].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="video-grid" id="video-grid">${state.videos.filter(v=>v.status==='Approved').map(videoCard).join('')}</div>`}
function videoCard(v){return `<article class="video-card"><div class="video-thumb"><span class="video-status">${v.status==='Approved'?'✓ Approved':'◷ In review'}</span><span class="play-button">▶</span><span style="position:absolute;right:18px;bottom:9px;font-size:38px;opacity:.28">${v.icon}</span></div><div class="video-details"><h4>${v.title}</h4><p>${v.subject} · ${v.grade}</p><div class="video-meta"><span>By ${v.teacher}</span><span>▶ 8:24</span></div></div></article>`}
function supportView(){return `${heading('Peer support','Ask a question, share what you know, grow together.',`<button class="btn btn-primary" data-action="ask-question">+ Ask a question</button>`)}<div class="columns"><section>${state.questions.map(q=>`<article class="question-card"><h4>${q.title}</h4><p>${q.subject} · Community question</p><div class="question-meta"><span>${q.asked}</span><span>♡ ${q.answers} answers</span><span>✓ Moderated</span></div><div class="answer"><b>Peer answer</b> — ${q.answer}</div><button class="text-link" data-action="answer-question">Add an answer →</button></article>`).join('')}</section><aside><section class="panel"><div class="panel-title"><h3>Study resources</h3><span>✦</span></div><div class="teacher-mini"><span class="stat-icon">▤</span><div class="teacher-mini-info"><b>Exam prep, together</b><small>Five ways to make a study plan</small></div></div><div class="teacher-mini"><span class="stat-icon">◷</span><div class="teacher-mini-info"><b>Focus in short bursts</b><small>A friendly guide to the Pomodoro method</small></div></div></section><div class="callout">Community tips: keep questions focused on learning. Never share personal contact details. Posts are simulated and moderated in this demo.</div></aside></div>`}
function pointsView(){return `${heading('Peer Points','A little thank-you for sharing what you know.',`<button class="btn btn-secondary" data-view="teach">Earn points by teaching</button>`)}<section class="hero" style="min-height:150px;background:linear-gradient(110deg,#edebff,#f5f2ff)"><div class="hero-copy"><div class="hero-kicker">YOUR LEARNING CREDITS</div><h2 style="font-size:24px;margin:7px 0">✳ ${state.points} Peer Points</h2><p>Earn points when you teach. Use them for eligible learning opportunities.</p></div></section><div class="stat-grid"><div class="stat-card"><span class="stat-icon">↗</span><div><div class="stat-value">${state.earned}</div><div class="stat-label">Points earned</div></div></div><div class="stat-card"><span class="stat-icon">↙</span><div><div class="stat-value">${state.spent}</div><div class="stat-label">Points used</div></div></div><div class="stat-card"><span class="stat-icon">✦</span><div><div class="stat-value">3</div><div class="stat-label">Teaching milestones</div></div></div><div class="stat-card"><span class="stat-icon">▤</span><div><div class="stat-value">${state.plan}</div><div class="stat-label">Membership</div></div></div></div><section class="panel"><div class="panel-title"><h3>Points activity</h3><span class="teacher-meta">All time</span></div><div class="session-row"><span class="stat-icon">↗</span><div class="session-info"><b>Maths session completed</b><small>Teaching reward · ${fmtDate(dayOffset(-2))}</small></div><b style="color:#439585">+40</b></div><div class="session-row"><span class="stat-icon">↗</span><div class="session-info"><b>Peer mentor milestone</b><small>Achievement · ${fmtDate(dayOffset(-7))}</small></div><b style="color:#439585">+80</b></div><div class="session-row"><span class="stat-icon">↙</span><div class="session-info"><b>Science learning session</b><small>Session credit · ${fmtDate(dayOffset(-10))}</small></div><b style="color:#8791a4">−40</b></div><div class="callout">Peer Points are virtual learning credits for use within PEERLY. They are not money and cannot be withdrawn or exchanged for cash.</div></section>`}
function plansView(){return `${heading('A plan that fits your pace','Your first three sessions each month are always on us.')}${state.classesUsed>=3&&state.plan==='Free'?`<div class="callout">You've reached your free learning limit for this month! Want to keep growing? Explore PEERLY Premium.</div>`:''}<div class="plan-grid"><article class="plan-card"><span class="plan-label">START EXPLORING</span><h3>Free</h3><div class="plan-price">₹0 <small>/ forever</small></div><p>A welcoming place to begin your learning journey.</p><ul class="plan-features"><li>Student registration & portfolio</li><li>Explore teachers and learning opportunities</li><li>3 learning sessions per month</li><li>Basic Peer Support</li><li>Learning progress tracking</li></ul><button class="btn ${state.plan==='Free'?'btn-quiet':'btn-secondary'}" data-action="select-free">${state.plan==='Free'?'Your current plan':'Choose Free'}</button></article><article class="plan-card featured"><span class="plan-ribbon">MOST POPULAR</span><span class="plan-label">KEEP GROWING</span><h3>PEERLY Premium</h3><div class="plan-price">₹199 <small>/ month</small></div><p>More room to explore every interest and opportunity.</p><ul class="plan-features"><li>Unlimited eligible session requests</li><li>Additional learning opportunities</li><li>Advanced discovery filters</li><li>Extended learning history</li><li>Priority discovery & premium resources</li></ul><button class="btn btn-primary" data-action="upgrade">${state.plan==='Premium'?'Manage Premium':'Try simulated checkout'}</button></article></div><div class="callout" style="max-width:750px;margin:15px auto">Checkout is simulated for this demo. No payment details are collected or charged. Under-18 learners need parent or guardian approval for a subscription.</div>`}
function notificationsView(){return `${heading('Your notifications','All the little updates that keep you in the loop.',`<button class="btn btn-quiet" data-action="mark-read">Mark all as read</button>`)}<section class="panel">${state.notifications.map((n,i)=>`<div class="session-row"><span class="stat-icon">${i===0?'✓':i===1?'✳':'▷'}</span><div class="session-info"><b>${n.title} ${n.unread?'<span class="tag teal">NEW</span>':''}</b><small>${n.body}</small></div><span class="session-time">${n.time}</span></div>`).join('')||'<div class="empty-state"><span>♧</span><b>You’re all caught up</b><p>New updates will show up here.</p></div>'}</section>`}
function teachView(){const myTeacher=state.user.role==='Student-teacher';return `${heading('Teaching & learning','Choose the way you’d like to grow today.')}<div class="split-card"><article class="role-card"><div class="role-symbol">⌕</div><h3>I want to learn</h3><p>Choose a subject, set your schedule and find a student-teacher who makes it click.</p><button class="btn btn-primary" data-view="discover">Find a learning buddy →</button></article><article class="role-card teaching"><div class="role-symbol">✦</div><h3>I want to teach</h3><p>Share what you know, choose your availability and help another student grow.</p><button class="btn btn-teal" data-action="teacher-setup">${myTeacher?'Manage my teaching profile':'Create teaching profile →'}</button></article></div><div class="section-heading"><div><h3>Your teaching requests</h3><p>Requests are shown here when you set up a teaching profile.</p></div></div>${myTeacher?`<section class="panel">${state.bookings.filter(b=>b.status==='Pending').map(b=>`<div class="session-row"><span class="stat-icon">♧</span><div class="session-info"><b>${b.subject} request · ${teacher(b.teacher).name}</b><small>${fmtDate(b.date)} at ${b.time} · ${b.format}</small></div><button class="btn-xs accept" data-action="accept" data-id="${b.id}">Accept</button><button class="btn-xs reject" data-action="decline" data-id="${b.id}">Decline</button></div>`).join('')||'<div class="empty-state"><span>♡</span><b>No pending requests</b><p>Your accepted classes and teaching schedule will appear here.</p></div>'}</section>`:`<div class="callout">When you create a demo teaching profile, this account will switch to student-teacher mode. You can switch back any time.</div>`}<div class="section-heading"><div><h3>Teaching made simple</h3><p>Set safe availability outside school hours.</p></div></div><div class="category-grid">${[['◷','Set your hours','After school & weekends'],['▤','Share your skills','Build a teaching profile'],['✳','Earn points','Celebrate milestones']].map(x=>`<div class="category-card"><div class="category-emoji">${x[0]}</div><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div>`}
function safetyView(){return `${heading('Safety & privacy','You are in control of what you share and how you learn.')}<div class="notice">PEERLY is designed with student safety in mind. This demo does not provide real account verification, guardian checks, or secure authentication.</div><section class="panel"><div class="panel-title"><h3>Privacy & permissions</h3><span class="teacher-meta">Saved on this device</span></div><div class="safety-grid">${[['profile','Discoverable student profile','Let other learners see your teaching interests.'],['guardian','Parent approval for bookings','Request guardian approval for sessions and plans.'],['offline','School-approved offline sessions','Only consider in-person sessions arranged through an approved school.'],['video','Video visibility after review','Sample videos are shown as already reviewed in this demo.']].map(x=>`<div class="safety-setting"><div><b>${x[1]}</b><small>${x[2]}</small></div><button class="toggle ${state.privacy[x[0]]?'on':''}" data-action="toggle-privacy" data-id="${x[0]}" aria-label="Toggle ${x[1]}"></button></div>`).join('')}</div></section><section class="panel" style="margin-top:14px"><div class="panel-title"><h3>Safety tools</h3></div><p class="teacher-meta">Keep personal phone numbers, home addresses and passwords private. There are no unrestricted private messages in this demo.</p><div class="teacher-actions"><button class="btn btn-quiet" data-action="report">⚑ Report a concern</button><button class="btn btn-quiet" data-action="block">⊘ Block a profile</button><button class="btn btn-quiet" data-action="parent-link">Link a parent</button></div></section>`}
function parentView(){return `${heading('Parent portal','A clear view of your child’s learning journey.',`<button class="btn btn-secondary" data-action="link-child">+ Link a child</button>`)}<div class="notice">Demo parent view · Parent and learner accounts are not linked through a real identity system.</div><section class="profile-hero">${avatar(state.user.name,'lav')}<div><div class="eyebrow">LINKED LEARNER · PENDING DEMO LINK</div><h2>${state.user.name}</h2><div class="teacher-meta">${state.user.grade} · Learning account</div><p class="profile-bio">Monitor approved learning activities, upcoming sessions and progress from one place.</p></div><span class="status-pill status-pending">Demo link</span></section><div class="stat-grid"><div class="stat-card"><span class="stat-icon">▦</span><div><div class="stat-value">${state.bookings.filter(b=>b.status==='Confirmed').length+1}</div><div class="stat-label">Upcoming sessions</div></div></div><div class="stat-card"><span class="stat-icon">✦</span><div><div class="stat-value">${state.plan}</div><div class="stat-label">Membership</div></div></div><div class="stat-card"><span class="stat-icon">✳</span><div><div class="stat-value">${state.points}</div><div class="stat-label">Peer Points</div></div></div><div class="stat-card"><span class="stat-icon">✓</span><div><div class="stat-value">On track</div><div class="stat-label">Learning progress</div></div></div></div><div class="columns"><section class="panel"><div class="panel-title"><h3>Sessions requiring approval</h3><span class="tag orange">Guardian review</span></div>${state.bookings.filter(b=>b.status==='Pending').map(b=>`<div class="session-row"><div class="session-info"><b>${b.subject} with ${teacher(b.teacher).name}</b><small>${fmtDate(b.date)} · ${b.time}</small></div><button class="btn-xs accept" data-action="parent-approve" data-id="${b.id}">Approve</button><button class="btn-xs reject" data-action="decline" data-id="${b.id}">Decline</button></div>`).join('')||'<div class="empty-state"><span>✓</span><b>No requests to review</b></div>'}</section><section class="panel"><div class="panel-title"><h3>Upcoming classes</h3><button data-view="calendar">View calendar →</button></div>${state.bookings.filter(b=>b.status==='Confirmed').map(sessionRow).join('')||'<p class="teacher-meta">No confirmed sessions yet.</p>'}</section></div><div class="section-heading"><div><h3>Membership & permissions</h3></div><button class="text-link" data-view="safety">Manage safety →</button></div><section class="panel"><div class="teacher-mini"><span class="stat-icon">✦</span><div class="teacher-mini-info"><b>${state.plan} plan</b><small>Payment details are not collected in this demo.</small></div><button class="btn btn-secondary" data-view="plans">Manage plan</button></div></section>`}
function educatorView(){return `${heading('Educator portal','Support approved learning, with student privacy at the centre.',`<button class="btn btn-secondary" data-action="educator-setup">Educator settings</button>`)}<div class="notice">Educator accounts are separate from student-teacher profiles. This demo shows sample programme activity; no school data is connected.</div><div class="stat-grid"><div class="stat-card"><span class="stat-icon">▤</span><div><div class="stat-value">8</div><div class="stat-label">Approved portfolios</div></div></div><div class="stat-card"><span class="stat-icon">▦</span><div><div class="stat-value">4</div><div class="stat-label">Programme sessions</div></div></div><div class="stat-card"><span class="stat-icon">♧</span><div><div class="stat-value">2</div><div class="stat-label">Items to review</div></div></div><div class="stat-card"><span class="stat-icon">✦</span><div><div class="stat-value">3</div><div class="stat-label">Student mentors</div></div></div></div><div class="columns"><section class="panel"><div class="panel-title"><h3>Approved programmes</h3><button data-action="programme">+ Create programme</button></div><div class="teacher-mini"><span class="stat-icon">∑</span><div class="teacher-mini-info"><b>Peer Maths Circle</b><small>Grades 9–10 · Thursdays after school</small></div><span class="status-pill">Active</span></div><div class="teacher-mini"><span class="stat-icon">⌘</span><div class="teacher-mini-info"><b>Young Coders Lab</b><small>Grades 8–11 · Saturdays</small></div><span class="status-pill">Active</span></div></section><section class="panel"><div class="panel-title"><h3>Recent learning portfolios</h3><button data-action="permission-note">Permission info</button></div><div class="teacher-mini">${avatar('Aarav Sharma','lav','small')}<div class="teacher-mini-info"><b>Aarav Sharma</b><small>Mathematics · Coding · Learner</small></div><button class="btn-xs" data-action="portfolio-permission">View</button></div><div class="teacher-mini">${avatar('Meera Iyer','blue','small')}<div class="teacher-mini-info"><b>Meera Iyer</b><small>Mathematics · Student-teacher</small></div><button class="btn-xs" data-action="portfolio-permission">View</button></div></section></div><div class="section-heading"><div><h3>Moderation queue</h3><p>Review flagged items using your school’s policies.</p></div><button class="text-link" data-view="admin">Open admin demo →</button></div><section class="panel"><div class="teacher-mini"><span class="stat-icon">▷</span><div class="teacher-mini-info"><b>“Cell structure walkthrough”</b><small>Sample upload · Awaiting review</small></div><button class="btn-xs accept" data-action="approve-video">Approve</button><button class="btn-xs reject" data-action="reject-video">Reject</button></div></section>`}
function adminView(){return `${heading('Admin dashboard','A snapshot of your PEERLY community and review queue.',`<span class="status-pill status-pending">Demo data</span>`)}<div class="admin-metric-grid"><div class="admin-metric"><b>2,481</b><small>Total student accounts</small></div><div class="admin-metric"><b>186</b><small>Student-teachers</small></div><div class="admin-metric"><b>94</b><small>Sessions this month</small></div><div class="admin-metric"><b>7</b><small>Needs review</small></div></div><div class="tab-row"><button class="tab-button ${adminTab==='overview'?'active':''}" data-action="admin-tab" data-id="overview">Overview</button><button class="tab-button ${adminTab==='profiles'?'active':''}" data-action="admin-tab" data-id="profiles">Profiles</button><button class="tab-button ${adminTab==='videos'?'active':''}" data-action="admin-tab" data-id="videos">Video moderation</button><button class="tab-button ${adminTab==='reports'?'active':''}" data-action="admin-tab" data-id="reports">Reports</button><button class="tab-button ${adminTab==='bookings'?'active':''}" data-action="admin-tab" data-id="bookings">Bookings</button></div>${adminContent()}`}
function adminContent(){if(adminTab==='profiles')return `<div class="table-wrap"><table><thead><tr><th>Student</th><th>Role</th><th>Grade</th><th>Status</th><th>Action</th></tr></thead><tbody>${[['Meera Iyer','Student-teacher','Grade 11','Approved'],['Kabir Malhotra','Student-teacher','Grade 10','Approved'],['Riya Shah','Learner','Grade 9','Review'],['Aarav Sharma','Learner','Grade 10','Active']].map(r=>`<tr><td class="table-name">${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td><span class="status-pill ${r[3]==='Review'?'status-pending':''}">${r[3]}</span></td><td><button class="btn-xs" data-action="admin-review">Review</button></td></tr>`).join('')}</tbody></table></div>`;if(adminTab==='videos')return `<div class="table-wrap"><table><thead><tr><th>Video</th><th>Creator</th><th>Subject</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.videos.map((v,i)=>`<tr><td class="table-name">${v.title}</td><td>${v.teacher}</td><td>${v.subject}</td><td><span class="status-pill ${v.status==='Approved'?'':'status-pending'}">${v.status}</span></td><td><button class="btn-xs accept" data-action="approve-video" data-id="${i}">Approve</button> <button class="btn-xs reject" data-action="reject-video" data-id="${i}">Reject</button></td></tr>`).join('')}</tbody></table></div>`;if(adminTab==='reports')return `<section class="panel"><div class="session-row"><span class="stat-icon">⚑</span><div class="session-info"><b>Sample report · Profile privacy concern</b><small>Submitted today · Queue example</small></div><span class="status-pill status-pending">Open</span><button class="btn-xs" data-action="admin-review">Review</button></div><div class="session-row"><span class="stat-icon">⚑</span><div class="session-info"><b>Sample report · Inappropriate content</b><small>Submitted yesterday · Queue example</small></div><span class="status-pill status-pending">Open</span><button class="btn-xs" data-action="admin-review">Review</button></div></section>`;if(adminTab==='bookings')return `<div class="table-wrap"><table><thead><tr><th>Subject</th><th>Student-teacher</th><th>Date</th><th>Format</th><th>Status</th></tr></thead><tbody>${state.bookings.map(b=>`<tr><td class="table-name">${b.subject}</td><td>${teacher(b.teacher).name}</td><td>${fmtDate(b.date)}</td><td>${b.format}</td><td><span class="status-pill ${b.status==='Pending'?'status-pending':''}">${b.status}</span></td></tr>`).join('')}</tbody></table></div>`;return `<div class="columns"><section class="panel"><div class="panel-title"><h3>Platform activity</h3><span class="tag teal">Last 30 days</span></div><div class="progress-list"><div><div class="progress-line"><b>Learning sessions</b><span>94 · +18%</span></div><div class="progress-track"><div class="progress-fill" style="width:76%"></div></div></div><div><div class="progress-line"><b>New student-teachers</b><span>32 · +12%</span></div><div class="progress-track"><div class="progress-fill" style="width:51%;background:#4da899"></div></div></div><div><div class="progress-line"><b>Premium memberships</b><span>114 · +9%</span></div><div class="progress-track"><div class="progress-fill" style="width:37%;background:#e6a253"></div></div></div></div></section><section class="panel"><div class="panel-title"><h3>Needs attention</h3><span class="tag orange">7 items</span></div><div class="teacher-mini"><span class="stat-icon">▷</span><div class="teacher-mini-info"><b>3 videos awaiting review</b><small>Review for safety and quality</small></div><button class="btn-xs" data-action="admin-tab" data-id="videos">Review</button></div><div class="teacher-mini"><span class="stat-icon">⚑</span><div class="teacher-mini-info"><b>2 community reports</b><small>Check reported profiles or posts</small></div><button class="btn-xs" data-action="admin-tab" data-id="reports">Review</button></div><div class="teacher-mini"><span class="stat-icon">▧</span><div class="teacher-mini-info"><b>2 profiles pending</b><small>Student-teacher profile queue</small></div><button class="btn-xs" data-action="admin-tab" data-id="profiles">Review</button></div></section></div><div class="section-heading"><div><h3>Recent bookings</h3><p>Demo activity across the platform.</p></div><button class="text-link" data-action="admin-tab" data-id="bookings">All bookings →</button></div><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Student-teacher</th><th>Date</th><th>Format</th><th>Status</th></tr></thead><tbody>${state.bookings.map(b=>`<tr><td class="table-name">${b.subject}</td><td>${teacher(b.teacher).name}</td><td>${fmtDate(b.date)}</td><td>${b.format}</td><td><span class="status-pill ${b.status==='Pending'?'status-pending':''}">${b.status}</span></td></tr>`).join('')}</tbody></table></div>`}
function openModal(title,body){const modal=document.getElementById('modal');modal.innerHTML=`<div class="modal-head"><div><h2>${title}</h2></div><button class="modal-close" data-action="close-modal">×</button></div>${body}`;document.getElementById('modal-backdrop').hidden=false}
function closeModal(){document.getElementById('modal-backdrop').hidden=true}
document.getElementById('modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function openSwitcher(){openModal('Switch your demo view',`<p class="teacher-meta" style="margin-bottom:14px">Explore PEERLY from different perspectives. Switching views is simulated.</p><div class="switcher-list">${[['Learner','Aarav Sharma','Grade 10'],['Student-teacher','Meera Iyer','Grade 11 · Student-teacher'],['Parent','Priya Sharma','Parent portal'],['Educator','Ms. Nandita Rao','School educator'],['Administrator','PEERLY Admin','Admin dashboard']].map((x,i)=>`<button class="switcher-option" data-action="switch-role" data-id="${i}">${avatar(x[1],['lav','mint','peach','blue','gold'][i],'small')}<span><b>${x[1]}</b><small>${x[0]} · ${x[2]}</small></span><span style="margin-left:auto;color:#a1a8b5">→</span></button>`).join('')}</div><div class="notice">Demo role switching does not create or verify a real account.</div>`)}
function openBooking(id){const t=teacher(id);selectedTeacher=id;openModal(`Request a class with ${t.name}`,`<p class="teacher-meta">Choose an after-school or weekend time. The teacher will confirm your request.</p><form id="booking-form"><div class="form-grid"><div class="field"><label>Subject</label><select name="subject">${t.subjects.map(s=>`<option>${s}</option>`).join('')}</select></div><div class="field"><label>Month</label><select name="month"><option>${new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric'}).format(new Date())}</option><option>${new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric'}).format(new Date(new Date().setMonth(new Date().getMonth()+1)))}</option></select></div><div class="field"><label>Available day</label><select name="day">${t.days.map(d=>`<option>${d}</option>`).join('')}</select></div><div class="field"><label>Date</label><input name="date" type="date" min="${dayOffset(1)}" value="${dayOffset(7)}" required></div><div class="field"><label>Time slot</label><select name="time">${t.slots.map(s=>`<option>${s}</option>`).join('')}</select></div><div class="field"><label>Number of sessions</label><select name="sessions"><option>1</option><option>2</option><option>4</option></select></div><div class="field"><label>Learning format</label><select name="format"><option>Online</option><option>School-approved offline</option></select></div><div class="field"><label>Learning level</label><select name="level"><option>Just starting</option><option>Some experience</option><option>Ready for a challenge</option></select></div></div><div class="notice">Parent or guardian approval may be required. This demo creates a pending request; no real message is sent.</div><div class="form-actions"><button class="btn btn-quiet" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit">Send class request</button></div></form>`);document.getElementById('booking-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target),date=data.get('date'),time=data.get('time'),weekday=new Intl.DateTimeFormat('en-US',{weekday:'short'}).format(new Date(date+'T12:00:00')),duplicate=state.bookings.some(b=>b.date===date&&b.time===time&&b.status!=='Declined'),sessions=Number(data.get('sessions')),reserved=state.bookings.filter(b=>b.status==='Pending').reduce((sum,b)=>sum+(b.sessions||1),0);if(weekday!==data.get('day')){toast(`Choose a ${data.get('day')} date to match the teacher’s availability.`);return}if(duplicate){toast('That time is already booked. Please choose another slot.');return}if(state.plan==='Free'&&state.classesUsed+reserved+sessions>3){closeModal();setView('plans');toast('This request exceeds your remaining free sessions.');return}const format=data.get('format');if(format==='School-approved offline'&&!state.privacy.offline){toast('Enable school-approved offline sessions in Safety & privacy first.');return}state.bookings.push({id:'b'+Date.now(),teacher:id,subject:data.get('subject'),date,time,sessions,status:'Pending',format});state.notifications.unshift({title:'Class request sent',body:`Your ${data.get('subject')} request is waiting for approval.`,time:'Just now',unread:true});save();closeModal();render();toast('Your class request is on its way!')})}
function openProfile(id){const t=teacher(id);openModal(t.name,`<div class="profile-hero" style="padding:14px;margin:0 0 14px">${avatar(t.name,t.tone)}<div><div class="eyebrow">STUDENT-TEACHER · ${t.grade.toUpperCase()}</div><h2 style="font-size:18px">${t.name}</h2><span class="rating">★ ${t.rating}</span> <span class="teacher-meta">${t.reviews} learner reviews</span></div></div><p class="profile-bio">${t.bio}</p><div><b style="font-size:10px">Subjects</b><div>${t.subjects.map(s=>`<span class="tag">${s}</span>`).join('')}</div></div><div style="margin-top:12px;font-size:10px;color:#7e899c"><b>Languages</b> · ${t.language}<br><b>Availability</b> · ${t.days.join(', ')} after school<br><b>Rate</b> · ${t.rate} Peer Points per session</div><div class="notice">Sample profile for the demo. Profile vetting and identity verification are not active.</div><div class="form-actions"><button class="btn btn-quiet" data-action="report">⚑ Report profile</button><button class="btn btn-primary" data-action="book" data-id="${id}">Request a class</button></div>`)}
function toast(message,success=true){const el=document.createElement('div');el.className=`toast ${success?'success':''}`;el.textContent=message;document.getElementById('toast-region').append(el);setTimeout(()=>el.remove(),3300)}
function handleAction(action,id){switch(action){case'register':openRegistration();break;case'close-modal':closeModal();break;case'profile':openProfile(id);break;case'book':closeModal();openBooking(id);break;case'accept':case'parent-approve':{const b=state.bookings.find(x=>x.id===id);if(b){b.status='Confirmed';state.classesUsed+=b.sessions||1;state.notifications.unshift({title:'Class confirmed',body:`Your ${b.subject} session is confirmed.`,time:'Just now',unread:true});save();render();toast('Session confirmed!')}break}case'decline':{const b=state.bookings.find(x=>x.id===id);if(b)b.status='Declined';save();render();toast('Request declined.');break}case'upgrade':if(state.user.role==='Learner'&&state.user.age&&Number(state.user.age)<18){openModal('Parent approval required',`<p>A parent or guardian must approve a PEERLY Premium subscription for a learner under 18.</p><div class="notice">This demo checkout never asks for or stores payment details.</div><div class="form-actions"><button class="btn btn-quiet" data-action="close-modal">Not now</button><button class="btn btn-primary" data-action="parent-approve-plan">Request parent approval</button></div>`)}else openModal('Simulated checkout',`<div class="notice">This is a demo checkout. No real payment provider is connected and no payment details are collected.</div><div class="panel"><b>PEERLY Premium</b><span style="float:right">₹199 / month</span><p class="teacher-meta">Unlimited eligible learning requests · Advanced filters · Premium resources</p></div><div class="form-actions"><button class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-upgrade">Confirm demo upgrade</button></div>`);break;case'confirm-upgrade':state.plan='Premium';state.notifications.unshift({title:'Welcome to PEERLY Premium',body:'Your demo membership is active.',time:'Just now',unread:true});save();closeModal();render();toast('Premium demo membership activated.');break;case'parent-approve-plan':state.notifications.unshift({title:'Parent approval requested',body:'Your Premium plan request is ready for guardian review.',time:'Just now',unread:true});save();closeModal();render();toast('Approval request created.');break;case'select-free':state.plan='Free';save();render();toast('Free plan selected.');break;case'mark-read':state.notifications.forEach(n=>n.unread=false);save();render();toast('Notifications marked as read.');break;case'edit-profile':openEditProfile();break;case'share-portfolio':toast('Portfolio sharing is a simulated preview.');break;case'upload-video':openUpload();break;case'ask-question':openQuestion();break;case'answer-question':openModal('Add a peer answer',`<div class="field"><label>Your helpful answer</label><textarea placeholder="Share an explanation or resource..."></textarea></div><div class="notice">Answers are simulated and require moderation before appearing publicly.</div><div class="form-actions"><button class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-answer">Submit for review</button></div>`);break;case'submit-answer':closeModal();toast('Answer submitted for review.');break;case'teacher-setup':openTeacherSetup();break;case'toggle-privacy':state.privacy[id]=!state.privacy[id];save();render();toast('Privacy setting updated.');break;case'report':openModal('Report a concern',`<p class="teacher-meta">Tell the safety team what happened. This demo records no external report.</p><div class="field"><label>Concern type</label><select><option>Inappropriate content</option><option>Profile or privacy concern</option><option>Safety concern</option><option>Other</option></select></div><div class="field" style="margin-top:12px"><label>Details</label><textarea placeholder="Add context without sharing personal contact details"></textarea></div><div class="form-actions"><button class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-report">Submit report</button></div>`);break;case'submit-report':closeModal();toast('Report submitted to the demo moderation queue.');break;case'block':openModal('Block a profile',`<p>This demo will hide the selected profile from your view. It does not send a real report.</p><div class="field"><label>Choose profile</label><select>${teachers.map(t=>`<option>${t.name}</option>`).join('')}</select></div><div class="form-actions"><button class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-block">Block profile</button></div>`);break;case'confirm-block':closeModal();toast('Profile hidden in this demo.');break;case'parent-link':case'link-child':openModal('Link a parent or child',`<p>In a live PEERLY account, linking requires an invitation and guardian verification.</p><div class="field"><label>${action==='link-child'?'Child’s':'Parent or guardian'} email</label><input type="email" placeholder="name@example.com"></div><div class="notice">No invitation is sent from this demo. Email is not saved.</div><div class="form-actions"><button class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="link-demo">Create demo link request</button></div>`);break;case'link-demo':closeModal();toast('Demo link request created.');break;case'switch-role':switchRole(Number(id));break;case'calendar-info':toast('Calendar month controls are a demo preview.');break;case'admin-tab':adminTab=id;render();break;case'admin-review':toast('Review opened in the simulated moderation queue.');break;case'approve-video':case'reject-video':{const i=Number(id);if(Number.isFinite(i)&&state.videos[i])state.videos[i].status=action==='approve-video'?'Approved':'Rejected';else state.videos.find(v=>v.status==='In review')&&(state.videos.find(v=>v.status==='In review').status=action==='approve-video'?'Approved':'Rejected');save();render();toast(action==='approve-video'?'Video approved in demo.':'Video rejected in demo.');break}case'programme':openModal('Create a school programme',`<div class="form-grid"><div class="field full"><label>Programme name</label><input placeholder="e.g. Creative Coding Club"></div><div class="field"><label>Grade range</label><select><option>Grades 8–10</option><option>Grades 9–12</option></select></div><div class="field"><label>Meeting day</label><select><option>Saturday</option><option>Thursday</option><option>Friday</option></select></div></div><div class="notice">Programme setup is simulated. No school accounts are connected.</div><div class="form-actions"><button class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="link-demo">Save programme</button></div>`);break;case'educator-setup':case'permission-note':case'portfolio-permission':toast('Portfolio access requires learner and guardian permission in a live account.');break}}
function switchRole(i){const rows=[['Aarav Sharma','Learner','Grade 10','home'],['Meera Iyer','Student-teacher','Grade 11','teach'],['Priya Sharma','Parent','Parent portal','parent'],['Ms. Nandita Rao','Educator','School educator','educator'],['PEERLY Admin','Administrator','Admin workspace','admin']];const row=rows[i];if(!row)return;state.user.name=row[0];state.user.role=row[1];state.user.grade=row[2];save();closeModal();setView(row[3]);toast(`Switched to ${row[1]} demo view.`)}
function openRegistration(){openModal('Create your PEERLY profile',`<p class="teacher-meta">Every student can learn and teach. Start with the side that feels right.</p><form id="registration-form"><div class="form-grid"><div class="field full"><label>I’m here to</label><select name="role"><option>Learner</option><option>Student-teacher</option></select></div><div class="field"><label>Name or display name</label><input name="name" placeholder="Your name" required></div><div class="field"><label>Age</label><input name="age" type="number" min="8" max="100" placeholder="Age" required></div><div class="field"><label>Class or grade</label><select name="grade">${[8,9,10,11,12].map(g=>`<option>Grade ${g}</option>`).join('')}</select></div><div class="field"><label>School (optional)</label><input name="school" placeholder="School name"></div><div class="field full"><label>Interests or skills</label><select name="interest"><option>Mathematics</option><option>Coding</option><option>Science</option><option>Art & design</option><option>Music</option><option>Languages</option></select></div><div class="field"><label>Learning style</label><select><option>Visual and interactive</option><option>Step by step</option><option>Practice together</option></select></div><div class="field"><label>Membership</label><select name="plan"><option>Free</option><option>Premium (parent approval)</option></select></div></div><div class="notice">Demo signup stores profile details only in this browser. It does not create a secure account or send information to PEERLY.</div><div class="form-actions"><button class="btn btn-quiet" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary">Create demo profile</button></div></form>`);document.getElementById('registration-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.user.name=f.get('name');state.user.age=f.get('age');state.user.grade=f.get('grade');state.user.role=f.get('role');state.plan='Free';if(f.get('plan')==='Premium (parent approval)')state.notifications.unshift({title:'Parent approval needed',body:'Premium membership requires guardian approval.',time:'Just now',unread:true});save();closeModal();setView(state.user.role==='Student-teacher'?'teach':'home');toast(`Welcome to PEERLY, ${state.user.name.split(' ')[0]}!`)}}
function openEditProfile(){openModal('Edit your portfolio',`<form id="profile-form"><div class="form-grid"><div class="field"><label>Display name</label><input name="name" value="${state.user.name}" required></div><div class="field"><label>Grade</label><select name="grade">${[8,9,10,11,12].map(g=>`<option ${state.user.grade===`Grade ${g}`?'selected':''}>Grade ${g}</option>`).join('')}</select></div><div class="field full"><label>About you</label><textarea name="bio">I love exploring how things work, especially in math and science.</textarea></div></div><div class="form-actions"><button class="btn btn-quiet" type="button" data-action="close-modal">Cancel</button><button class="btn btn-primary">Save changes</button></div></form>`);document.getElementById('profile-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.user.name=f.get('name');state.user.grade=f.get('grade');save();closeModal();render();toast('Portfolio updated.')}}
function openTeacherSetup(){openModal('Create your teaching profile',`<form id="teacher-form"><div class="form-grid"><div class="field"><label>Display name</label><input name="name" value="${state.user.name}" required></div><div class="field"><label>Grade</label><select name="grade">${[8,9,10,11,12].map(g=>`<option ${state.user.grade===`Grade ${g}`?'selected':''}>Grade ${g}</option>`).join('')}</select></div><div class="field"><label>Skills you can teach</label><select name="subject"><option>Mathematics</option><option>Coding</option><option>Science</option><option>Art</option><option>Music</option><option>English</option></select></div><div class="field"><label>Teaching language</label><select><option>English</option><option>English, Hindi</option><option>Other</option></select></div><div class="field full"><label>Short introduction</label><textarea placeholder="What do you enjoy teaching?" required></textarea></div><div class="field"><label>Available days</label><select><option>Weekdays after school</option><option>Weekends</option><option>Both</option></select></div><div class="field"><label>Learning format</label><select><option>Online</option><option>School-approved offline</option></select></div></div><div class="notice">Teaching profiles and identity checks are simulated. Never share personal phone numbers or your home address.</div><div class="form-actions"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Create profile</button></div></form>`);document.getElementById('teacher-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.user.name=f.get('name');state.user.role='Student-teacher';state.user.grade=f.get('grade');save();closeModal();setView('teach');toast('Your demo teaching profile is ready!')}}
function openUpload(){openModal('Share a learning video',`<form id="video-form"><div class="form-grid"><div class="field full"><label>Video title</label><input name="title" placeholder="e.g. Algebra made visual" required></div><div class="field"><label>Subject</label><select name="subject"><option>Mathematics</option><option>Coding</option><option>Science</option><option>Art</option><option>Music</option></select></div><div class="field"><label>Grade level</label><select><option>Grades 9–11</option><option>Grades 8–10</option><option>All levels</option></select></div><div class="field full"><label>Description</label><textarea name="description" placeholder="What will learners discover?"></textarea></div><div class="field full"><label>Video preview</label><input type="file" accept="video/*"><small class="teacher-meta">File upload is shown for the demo; the file is not stored.</small></div></div><div class="notice">Your video will be marked “In review” and will not appear in the public library until approved.</div><div class="form-actions"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Submit for review</button></div></form>`);document.getElementById('video-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.videos.unshift({title:f.get('title'),subject:f.get('subject'),teacher:state.user.name,grade:'All levels',status:'In review',icon:'▷'});save();closeModal();render();toast('Video submitted to moderation.')}}
function openQuestion(){openModal('Ask the community',`<form id="question-form"><div class="field"><label>Your question</label><input name="title" placeholder="What are you curious about?" required></div><div class="field" style="margin-top:12px"><label>Subject</label><select name="subject"><option>Mathematics</option><option>Science</option><option>Coding</option><option>Languages</option><option>Other</option></select></div><div class="field" style="margin-top:12px"><label>Add details</label><textarea name="details" placeholder="A little more context helps peers answer."></textarea></div><div class="notice">Community posts are moderated in a live service. Do not add personal information.</div><div class="form-actions"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancel</button><button class="btn btn-primary">Submit question</button></div></form>`);document.getElementById('question-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.questions.unshift({title:f.get('title'),subject:f.get('subject'),asked:'You · Just now',answers:0,answer:'This question is awaiting a helpful peer response.'});save();closeModal();render();toast('Question added to the demo community.')}}
content.addEventListener('input',e=>{if(e.target.id==='discover-search'){discoverQuery=e.target.value}});content.addEventListener('change',e=>{if(e.target.id==='subject-select'){discoverSubject=e.target.value;render()}if(e.target.id==='grade-select'){discoverGrade=e.target.value;render()}if(e.target.name==='side-subject'){discoverSubject=e.target.value;render()}if(e.target.id==='video-subject'||e.target.id==='video-search'){const q=document.getElementById('video-search')?.value.toLowerCase()||'',sub=document.getElementById('video-subject')?.value||'All subjects';const list=state.videos.filter(v=>v.status==='Approved'&&(sub==='All subjects'||v.subject===sub)&&(!q||v.title.toLowerCase().includes(q)||v.subject.toLowerCase().includes(q)));document.getElementById('video-grid').innerHTML=list.map(videoCard).join('')}});
content.addEventListener('click',e=>{if(e.target.id==='search-button'){discoverQuery=document.getElementById('discover-search').value;discoverSubject=document.getElementById('subject-select').value;discoverGrade=document.getElementById('grade-select').value;render()}});
render();
